import string

_HEX_DIGITS = set(string.hexdigits)


def even_or_odd(N):
    """Write a python function to check whether the hexadecimal number is even or odd."""
    if isinstance(N, int):
        return "Even" if N % 2 == 0 else "Odd"
    if not isinstance(N, str):
        raise TypeError("N must be a hexadecimal string or an integer")

    s = N.strip()
    if not s:
        raise ValueError("empty hexadecimal number")
    if s[0] in "+-":
        s = s[1:]
        if not s:
            raise ValueError(f"invalid hexadecimal number: {N!r}")
    if s[:2].lower() == "0x":
        s = s[2:]
        if not s:
            raise ValueError(f"invalid hexadecimal number: {N!r}")
    if any(char not in _HEX_DIGITS for char in s):
        raise ValueError(f"invalid hexadecimal number: {N!r}")

    # Parity of a hexadecimal number depends only on its last digit.
    return "Even" if int(s[-1], 16) % 2 == 0 else "Odd"
